effect.shader:
vec4 s(vec2 uv){ return texture2DCv(inputImg.texture, uv); }
float rnd(vec2 p){ return fract(sin(dot(p,vec2(12.9898,78.233)))*43758.5453); }
void main(){
  vec2 uv = acScreenNorm;
  vec2 px = 1.0/acScreenSize;
  float baseAng = radians(angle);
  int ic = int(count+0.5);
  float seg = 3.14159265359 * 2.0 / max(1.0, float(ic));

  // --- march setup (ray-invariant: hoisted out of both loops) ---
  // The original walked positions 0 .. steps-1 in 1-unit increments. We walk
  // the same extent in at most 96 taps: stride is set so the LAST tap still
  // lands exactly on steps-1 (ray length unchanged) and the exponential
  // weight curve is sampled at those same positions (falloff shape unchanged).
  float len = length;
  int steps = int(min(256.0, len));
  int nStep = steps < 96 ? steps : 96;
  float fS = float(steps);
  float fN = float(nStep);
  float stride = (nStep > 1) ? ((fS - 1.0) / (fN - 1.0)) : 1.0;
  float q = exp(-decay*stride);

  // Energy match: closed-form geometric sums of the old and new weight sets,
  // so total accumulated brightness is identical, not merely proportional.
  float gain;
  if (decay < 1.0e-5) {
    gain = fS / max(1.0, fN);
  } else {
    float sumOld = (1.0 - exp(-decay*fS))          / max(1.0e-8, 1.0 - exp(-decay));
    float sumNew = (1.0 - exp(-decay*stride*fN))   / max(1.0e-8, 1.0 - q);
    gain = sumOld / max(1.0e-8, sumNew);
  }

  // The old inner "blur" ran a FIXED 1px 3x3 tent regardless of soft: 9 fetches
  // whose weights sum to 16 but which divided by 14. One fetch times 8/7
  // reproduces its gain exactly; only the sub-pixel softening is dropped.
  float wScale = gain * (soft > 0.0 ? (8.0/7.0) : 1.0);
  // Upper bound on all remaining taps of a ray (source assumed <= 1):
  // w * wScale / (1-q). Break once that can no longer reach 1/255.
  float tailK = wScale / max(1.0e-6, 1.0 - q);

  vec4 acc = vec4(0.0);
  for(int k=0;k<16;k++){
    if(k>=ic) break;
    float a = baseAng + seg*float(k);
    vec2 dir = vec2(cos(a), sin(a));
    float w = 1.0;
    for(int i=0;i<96;i++){
      if(i>=nStep) break;
      if(w*tailK < 0.001) break;
      float fi = float(i)*stride;
      float j = 0.0;
      if(jitter > 0.0) j = (rnd(uv.xy+fi) - 0.5) * jitter;
      vec2 offs = (-dir * fi * spread + dir * j) * px;
      acc += s(uv + offs) * (w*wScale);
      w *= q;
    }
  }
  vec4 rays = acc;
  gl_FragColor = vec4(rays.rgb, clamp(rays.a,0.0,1.0));
}
